function toolCopyPlan(view, resolve) {
  if (view.agentStatus) return copyPlan({ kind: "mcp", result: view.agentStatus.body });
  if (view.paseo?.agentOperation) return copyPlan({
    kind: "mcp",
    result: stringifyValue(view.paseo.agentOperation.result),
    args: view.paseo.agentOperation.arguments
  });
  if (view.paseo?.catalog) return copyPlan({
    kind: "mcp",
    result: stringifyValue(view.paseo.catalog.result),
    args: view.paseo.catalog.arguments
  });
  if (view.paseo?.sendAgentPrompt) return copyPlan({
    kind: "mcp",
    result: stringifyValue(view.paseo.sendAgentPrompt.result),
    args: view.paseo.sendAgentPrompt.arguments
  });
  if (view.questionData) {
    return copyPlan({
      kind: "mcp",
      args: { questions: view.questionData.questions },
      result: view.text ?? view.output ?? stringifyValue(view.questionData.answers ?? view.questionData.result)
    });
  }
  if (view.activity) {
    const first = view.activity.sections[0];
    return copyPlan({ kind: "reasoning", text: first?.text ?? view.activity.target ?? view.activity.verb });
  }
  switch (view.tool) {
    case "bash":
    case "shell":
    case "git":
      return copyPlan({
        kind: "shell",
        command: view.shell?.command ?? view.command ?? "",
        stdout: view.shell?.stdout ?? view.output,
        stderr: view.shell?.stderr
      });
    case "read":
    case "write":
      return copyPlan({
        kind: view.tool,
        absolutePath: view.filePath ? resolve(view.filePath) : "",
        content: view.code
      });
    case "edit":
      return copyPlan({
        kind: "edit",
        absolutePath: view.filePath ? resolve(view.filePath) : "",
        patch: view.diff,
        newString: view.newString
      });
    case "search":
      return copyPlan({
        kind: "search",
        query: view.search?.query ?? "",
        summary: view.search?.annotations?.join("\n\n"),
        files: view.search?.files?.map(resolve) ?? view.search?.webResults?.map((row) => row.url)
      });
    case "mcp":
      return copyPlan({
        kind: "mcp",
        result: stringifyValue(view.mcp?.result),
        args: view.mcp?.arguments ?? view.input
      });
    case "fetch":
      return copyPlan({ kind: "fetch", url: view.fetch?.url ?? "", result: view.fetch?.result });
    case "worktree_setup":
      return copyPlan({
        kind: "worktree",
        absolutePath: view.worktree?.worktreePath ? resolve(view.worktree.worktreePath) : "",
        log: view.worktree?.log
      });
    case "sub_agent":
      return copyPlan({
        kind: "sub-agent",
        description: view.subAgent?.description,
        prompt: view.subAgent?.prompt,
        log: view.subAgent?.log
      });
    case "plan":
    case "plain_text":
    case "thinking":
      return copyPlan({
        kind: "reasoning",
        text: view.text ?? view.thinking?.text ?? view.code ?? view.output ?? ""
      });
    default:
      return copyPlan({ kind: "mcp", result: view.output ?? view.github?.text, args: view.input });
  }
}

